INSERT INTO vocabulary (simplified,traditional,pinyin,meaning,korean_hanja_reading,characters,pinyin_normalized) SELECT '请','請','qǐng','부탁하다','청','[{"char":"请","traditional":"請","decomposition":{"type":"layout","layout":"left-right","children":[{"type":"character","value":"讠"},{"type":"character","value":"青"}]}}]','qing' WHERE NOT EXISTS (SELECT 1 FROM vocabulary WHERE simplified='请' AND pinyin='qǐng' AND meaning='부탁하다');
INSERT INTO vocabulary (simplified,traditional,pinyin,meaning,korean_hanja_reading,characters,exam_tags,pinyin_normalized) SELECT '好','好','hǎo','좋다','호','[{"char":"好","traditional":"好","decomposition":{"type":"layout","layout":"left-right","children":[{"type":"character","value":"女"},{"type":"character","value":"子"}]}}]','["2026-midterm","2026-final"]','hao' WHERE NOT EXISTS (SELECT 1 FROM vocabulary WHERE simplified='好' AND pinyin='hǎo' AND meaning='좋다');
INSERT INTO vocabulary (simplified,traditional,pinyin,meaning,korean_hanja_reading,characters,exam_tags,pinyin_normalized) SELECT '你','你','nǐ','너','니','[{"char":"你","traditional":"你","decomposition":{"type":"layout","layout":"left-right","children":[{"type":"character","value":"亻"},{"type":"character","value":"尔"}]}}]','["2026-midterm"]','ni' WHERE NOT EXISTS (SELECT 1 FROM vocabulary WHERE simplified='你' AND pinyin='nǐ' AND meaning='너');
INSERT INTO vocabulary (simplified,traditional,pinyin,meaning,korean_hanja_reading,characters,pinyin_normalized) SELECT '吗','嗎','ma','의문을 나타내는 어기조사','마','[{"char":"吗","traditional":"嗎","decomposition":{"type":"layout","layout":"left-right","children":[{"type":"character","value":"口"},{"type":"character","value":"马"}]}}]','ma' WHERE NOT EXISTS (SELECT 1 FROM vocabulary WHERE simplified='吗' AND pinyin='ma' AND meaning='의문을 나타내는 어기조사');
