INSERT INTO vocabulary (simplified,traditional,pinyin,meaning,korean_hanja_reading,characters,pinyin_normalized) SELECT '情','情','qíng','감정','정','[{"char":"情","traditional":"情","decomposition":{"type":"layout","layout":"left-right","children":[{"type":"character","value":"忄"},{"type":"character","value":"青"}]}}]','qing' WHERE NOT EXISTS (SELECT 1 FROM vocabulary WHERE simplified='情' AND pinyin='qíng' AND meaning='감정');
INSERT INTO vocabulary (simplified,traditional,pinyin,meaning,korean_hanja_reading,characters,pinyin_normalized) SELECT '晴','晴','qíng','날이 개다','청','[{"char":"晴","traditional":"晴","decomposition":{"type":"layout","layout":"left-right","children":[{"type":"character","value":"日"},{"type":"character","value":"青"}]}}]','qing' WHERE NOT EXISTS (SELECT 1 FROM vocabulary WHERE simplified='晴' AND pinyin='qíng' AND meaning='날이 개다');
INSERT INTO vocabulary (simplified,traditional,pinyin,meaning,korean_hanja_reading,characters,exam_tags,pinyin_normalized) SELECT '学校','學校','xuéxiào','학교','학교','[{"char":"学","traditional":"學","decomposition":{"type":"layout","layout":"top-bottom","children":[{"type":"layout","layout":"top-bottom","children":[{"type":"character","value":"⺍"},{"type":"character","value":"冖"}]},{"type":"character","value":"子"}]}},{"char":"校","traditional":"校","decomposition":{"type":"layout","layout":"left-right","children":[{"type":"character","value":"木"},{"type":"character","value":"交"}]}}]','["2026-final"]','xuexiao' WHERE NOT EXISTS (SELECT 1 FROM vocabulary WHERE simplified='学校' AND pinyin='xuéxiào' AND meaning='학교');
INSERT INTO vocabulary (simplified,traditional,pinyin,meaning,korean_hanja_reading,characters,pinyin_normalized) SELECT '学生','學生','xuéshēng','학생','학생','[{"char":"学","traditional":"學","decomposition":{"type":"layout","layout":"top-bottom","children":[{"type":"layout","layout":"top-bottom","children":[{"type":"character","value":"⺍"},{"type":"character","value":"冖"}]},{"type":"character","value":"子"}]}},{"char":"生","traditional":"生"}]','xuesheng' WHERE NOT EXISTS (SELECT 1 FROM vocabulary WHERE simplified='学生' AND pinyin='xuéshēng' AND meaning='학생');
INSERT INTO vocabulary (simplified,traditional,pinyin,meaning,korean_hanja_reading,characters,pinyin_normalized) SELECT '老师','老師','lǎoshī','선생님','노사','[{"char":"老","traditional":"老"},{"char":"师","traditional":"師"}]','laoshi' WHERE NOT EXISTS (SELECT 1 FROM vocabulary WHERE simplified='老师' AND pinyin='lǎoshī' AND meaning='선생님');
