INSERT INTO vocabulary (simplified,traditional,pinyin,meaning,korean_hanja_reading,characters,pinyin_normalized) SELECT '休','休','xiū','쉬다','휴','[{"char":"休","traditional":"休","decomposition":{"type":"layout","layout":"left-right","children":[{"type":"character","value":"亻"},{"type":"character","value":"木"}]}}]','xiu' WHERE NOT EXISTS (SELECT 1 FROM vocabulary WHERE simplified='休' AND pinyin='xiū' AND meaning='쉬다');
INSERT INTO vocabulary (simplified,traditional,pinyin,meaning,korean_hanja_reading,characters,pinyin_normalized) SELECT '打','打','dǎ','치다','타','[{"char":"打","traditional":"打","decomposition":{"type":"layout","layout":"left-right","children":[{"type":"character","value":"扌"},{"type":"character","value":"丁"}]}}]','da' WHERE NOT EXISTS (SELECT 1 FROM vocabulary WHERE simplified='打' AND pinyin='dǎ' AND meaning='치다');
INSERT INTO sentences (korean,chinese,tokens,explanation,exam_tags) SELECT '너는 학생이니?','你是学生吗？','["你","是","学生","吗"]','평서문 끝에 吗를 붙여 예/아니요 의문문을 만듭니다.','["2026-midterm"]' WHERE NOT EXISTS (SELECT 1 FROM sentences WHERE korean='너는 학생이니?' AND chinese='你是学生吗？');
INSERT INTO sentences (korean,chinese,tokens,explanation) SELECT '너는 이름이 뭐니?','你叫什么名字？','["你","叫","什么","名字"]','什么로 묻는 단순 의문절에는 吗를 함께 쓰지 않습니다.' WHERE NOT EXISTS (SELECT 1 FROM sentences WHERE korean='너는 이름이 뭐니?' AND chinese='你叫什么名字？');
INSERT INTO sentences (korean,chinese,tokens,explanation) SELECT '나는 중국어를 공부한다.','我学习中文。','["我","学习","中文"]','주어 + 동사 + 목적어 순서입니다.' WHERE NOT EXISTS (SELECT 1 FROM sentences WHERE korean='나는 중국어를 공부한다.' AND chinese='我学习中文。');
INSERT INTO sentences (korean,chinese,tokens,explanation) SELECT '나는 선생님이 아니다.','我不是老师。','["我","不","是","老师"]','不는 是 앞에 둡니다.' WHERE NOT EXISTS (SELECT 1 FROM sentences WHERE korean='나는 선생님이 아니다.' AND chinese='我不是老师。');
INSERT INTO grammar_rules (title,explanation,correct_examples,wrong_examples,tags,questions,exam_tags) SELECT '吗와 의문사','같은 단순 의문절에서는 什么와 吗를 함께 쓰지 않습니다. 你知道他喜欢什么吗？처럼 내포절이 있는 문장은 별개입니다.','["你叫什么名字？","你知道他喜欢什么吗？"]','["你叫什么名字吗？"]','["의문문","초급"]','[{"type":"error","prompt":"你叫什么名字吗？에서 불필요한 부분은?","options":["你","叫","什么","吗"],"answer":"吗"},{"type":"blank","prompt":"你___什么名字？","options":["叫","是","吗","不"],"answer":"叫"},{"type":"order","prompt":"너는 학생이니? — 문장을 배열하세요.","tokens":["你","是","学生","吗"],"answer":"你是学生吗？"}]','["2026-midterm"]' WHERE NOT EXISTS (SELECT 1 FROM grammar_rules WHERE title='吗와 의문사');
INSERT INTO grammar_rules (title,explanation,correct_examples,wrong_examples,tags,questions) SELECT '是의 부정','是 앞에 不를 놓아 부정합니다.','["我不是老师。"]','["我是老师不。","我是不老师。"]','["부정"]','[{"type":"blank","prompt":"我___是老师。","options":["不","吗","什么","谁"],"answer":"不"}]' WHERE NOT EXISTS (SELECT 1 FROM grammar_rules WHERE title='是의 부정');
INSERT INTO grammar_rules (title,explanation,correct_examples,wrong_examples,tags,questions) SELECT '기본 어순','초급 평서문은 주어 + 동사 + 목적어 순서로 구성합니다.','["我学习中文。"]','["我中文学习。"]','["어순"]','[{"type":"order","prompt":"나는 중국어를 공부한다.","tokens":["我","学习","中文"],"answer":"我学习中文。"}]' WHERE NOT EXISTS (SELECT 1 FROM grammar_rules WHERE title='기본 어순');
INSERT INTO culture_items (category,question,answer,distractors,explanation,exam_tags) SELECT '명절','중국의 음력 새해 명절은?','춘절','["중추절","단오절","청명절"]','춘절(春节)은 음력 새해를 맞이하는 명절입니다.','["2026-midterm"]' WHERE NOT EXISTS (SELECT 1 FROM culture_items WHERE category='명절' AND question='중국의 음력 새해 명절은?' AND answer='춘절');
INSERT INTO culture_items (category,question,answer,distractors,explanation) SELECT '음식','중추절에 대표적으로 먹는 음식은?','월병','["쭝쯔","탕위안","자오쯔"]','월병(月饼)은 중추절의 대표 음식입니다.' WHERE NOT EXISTS (SELECT 1 FROM culture_items WHERE category='음식' AND question='중추절에 대표적으로 먹는 음식은?' AND answer='월병');
INSERT INTO culture_items (category,question,answer,distractors,explanation) SELECT '지역','중국의 수도는?','베이징','["상하이","광저우","시안"]','베이징(北京)이 수도입니다.' WHERE NOT EXISTS (SELECT 1 FROM culture_items WHERE category='지역' AND question='중국의 수도는?' AND answer='베이징');
INSERT INTO culture_items (category,question,answer,distractors,explanation) SELECT '숫자/색 상징','중국에서 경사와 행운을 상징하는 대표적인 색은?','빨간색','["흰색","검은색","회색"]','빨간색은 명절과 결혼식 등 경사스러운 상황에서 널리 사용합니다.' WHERE NOT EXISTS (SELECT 1 FROM culture_items WHERE category='숫자/색 상징' AND question='중국에서 경사와 행운을 상징하는 대표적인 색은?' AND answer='빨간색');
